"""Engineering Math unit 15: complex analysis past unit 14 — mappings, contour integrals, singularities, residues.

Unit 14 stops at the Cauchy–Riemann equations, one use of Cauchy's formula and a first residue. This unit follows
the four blocks of the Cambridge Part IB Complex Analysis schedule (cambridge-ib-complex, read in full) and turns
each theorem into what it lets you compute. Verify expressions go another way where one exists: a contour integral
by parametrising it, a real integral by its residue taken as a limit, a Laurent coefficient by differentiating in
w = 1/z. Z is the verifier's complex symbol.
"""
from opl_dsl import Q

FILE, FRAMEWORK, PRACTICE = "em-complex", "engineering-math", "P1"
MC = ["{{o1}}", "{{o2}}", "{{o3}}", "{{o4}}"]
CF, CT, CS = "cplx.conformal", "cplx.contour", "cplx.series"
A, C, S, R = ("cambridge-ib-complex:A", "cambridge-ib-complex:C", "cambridge-ib-complex:S", "cambridge-ib-complex:R")


def facts(name, skill, rows, explain):
    return Q(name, skill, "{{q}}", pace="recall",
             cases=[{"q": q, "o1": a, "o2": b, "o3": c, "o4": d} for q, a, b, c, d in rows],
             choice=MC, correct="0", verify="authored", explain=explain)


